{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OMNI_INV_EXPOSURE_OFFLINE as with low_str_skus as ( select * from ( with str_deets as ( select * FROM snitch_db.maplemonk.str_test_2 where store_perf_flag = \'Low\'), inward_deets as ( select final_store, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN LEFT( sku,LENGTH(sku)- LENGTH(REVERSE(SUBSTRING(REVERSE(sku), 1, POSITION(\'-\', REVERSE(sku)) - 1))) - 1 ) ELSE sku end as sku_group, min(inwarded_date) as inward_date from snitch_db.maplemonk.b2b_journey group by 1,2 ), offline_master_deets as (select branch_code, marketplace_mapped, upper(sku_group) as sku_group, first_order_date, sales_last_30_days from snitch_db.maplemonk.offline_master ) select a.*, coalesce(b.inward_date,c.first_order_date) as inward, c.sales_last_30_days from str_deets a left join inward_deets b on a.marketplace_mapped = b.final_store and a.sku_group = b.sku_group left join offline_master_deets c on a.branch_code= c.branch_code and a.sku_group = c.sku_group where a.branch_code in ( 3,4,6,7,13,14,15,18,19,21,22,23,26,29,30,38,39,40,42,47,49,50,51,52, 56,57,64,68,69,73,75,77,79,82,85,86,87,88,89,90,91,96,97,99,100, 102,103,104,106,107,109,110,111,114,116,120,123,125,128,130,132, 134,135,136,139,141,142 ) and ( inward < current_date - 30 or inward is null ) and a.sku_group not like \'NT%\' and a.sku_group not like \'%CB%\' and a.sku_group not like \'%GIFT%\' and lower(a.new_category) not like \'%shoes%\' and a.closing_inventory + a.jit_qty > 0 and coalesce(c.sales_last_30_days, 0) < 10) ), no_replen_skus as ( SELECT * FROM ( WITH wh_inv AS ( SELECT warehouse_location AS zone, UPPER(sku_group) AS sku_group, COALESCE(xs_units, 0) AS wh_xs, COALESCE(s_units, 0) AS wh_s, COALESCE(m_units, 0) AS wh_m, COALESCE(l_units, 0) AS wh_l, COALESCE(xl_units, 0) AS wh_xl, COALESCE(xxl_units, 0) AS wh_xxl, COALESCE(xl3_units, 0) AS wh_3xl, COALESCE(xl4_units, 0) AS wh_4xl, COALESCE(xl5_units, 0) AS wh_5xl, COALESCE(xl6_units, 0) AS wh_6xl FROM snitch_db.maplemonk.availability_master_v2_merged ), store_zone AS ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ), store_cut_size AS ( SELECT om.branch_code, sz.zone, om.marketplace_mapped, UPPER(om.sku_group) AS sku_group, om.inventory, om.jit_qty, om.new_category, om.designs, om.collar_new, om.sleeve_type, om.fit, om.style, om.material_new, CASE WHEN COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xs, CASE WHEN COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_s, CASE WHEN COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_m, CASE WHEN COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_l, CASE WHEN COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xl, CASE WHEN COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xxl, CASE WHEN COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_3xl, CASE WHEN COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_4xl, CASE WHEN COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_5xl, CASE WHEN COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_6xl, COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) AS qty_xs, COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) AS qty_s, COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) AS qty_m, COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) AS qty_l, COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) AS qty_xl, COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) AS qty_xxl, COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) AS qty_3xl, COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) AS qty_4xl, COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) AS qty_5xl, COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) AS qty_6xl FROM snitch_db.maplemonk.offline_master om LEFT JOIN store_zone sz ON om.branch_code = sz.branch_code WHERE om.new_category NOT IN (\'Belts\', \'Bags\', \'Shoes\', \'Sunglasses\', \'Perfumes\') AND om.inventory + om.jit_qty > 0 AND om.base_stock IS NOT NULL ), cut_size_flagged AS ( SELECT s.*, CASE WHEN LEFT(s.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (s.s_3xl + s.s_4xl + s.s_5xl + s.s_6xl) < 3 THEN \'YES\' WHEN LEFT(s.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (s.s_s + s.s_m + s.s_l + s.s_xl) < 3 OR (s.s_xs + s.s_s + s.s_m + s.s_l + s.s_xl + s.s_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_at_store FROM store_cut_size s ), cut_size_only AS ( SELECT * FROM cut_size_flagged where cut_size_at_store in (\'YES\') ), with_replenishment AS ( SELECT c.*, CASE WHEN c.qty_xs + COALESCE(w.wh_xs,0) > 2 THEN 1 ELSE 0 END AS r_xs, CASE WHEN c.qty_s + COALESCE(w.wh_s,0) > 3 THEN 1 ELSE 0 END AS r_s, CASE WHEN c.qty_m + COALESCE(w.wh_m,0) > 5 THEN 1 ELSE 0 END AS r_m, CASE WHEN c.qty_l + COALESCE(w.wh_l,0) > 5 THEN 1 ELSE 0 END AS r_l, CASE WHEN c.qty_xl + COALESCE(w.wh_xl,0) > 3 THEN 1 ELSE 0 END AS r_xl, CASE WHEN c.qty_xxl + COALESCE(w.wh_xxl,0) > 2 THEN 1 ELSE 0 END AS r_xxl, CASE WHEN c.qty_3xl + COALESCE(w.wh_3xl,0) > 3 THEN 1 ELSE 0 END AS r_3xl, CASE WHEN c.qty_4xl + COALESCE(w.wh_4xl,0) > 3 THEN 1 ELSE 0 END AS r_4xl, CASE WHEN c.qty_5xl + COALESCE(w.wh_5xl,0) > 3 THEN 1 ELSE 0 END AS r_5xl, CASE WHEN c.qty_6xl + COALESCE(w.wh_6xl,0) > 3 THEN 1 ELSE 0 END AS r_6xl FROM cut_size_only c LEFT JOIN wh_inv w ON w.zone = c.zone AND w.sku_group = c.sku_group ), final AS ( SELECT r.*, CASE WHEN LEFT(r.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (r.r_3xl + r.r_4xl + r.r_5xl + r.r_6xl) < 3 THEN \'YES\' WHEN LEFT(r.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (r.r_s + r.r_m + r.r_l + r.r_xl) < 3 OR (r.r_xs + r.r_s + r.r_m + r.r_l + r.r_xl + r.r_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_after_replenishment FROM with_replenishment r ) SELECT branch_code, zone, marketplace_mapped, sku_group, inventory, jit_qty, new_category, designs, collar_new, sleeve_type, fit, style, material_new, cut_size_at_store, cut_size_after_replenishment FROM final WHERE cut_size_after_replenishment = \'YES\' and branch_code in (3, 4, 6, 7, 13, 14, 15, 18, 19, 21, 22, 23, 26, 29, 30, 38, 39, 40, 42, 47, 49, 50, 51, 52, 56, 57, 64, 68, 69, 73, 75, 77, 79, 82, 85, 86, 87, 88, 89, 90, 91, 96, 97, 99, 100,102,103,104,106,107,109,110,111,114,116,120,123,125,128,130,132,134,135,136,139,141,142) ) ), long_tail as ( SELECT branch_code, UPPER(sku_group) AS sku_group, INVENTORY + jit_qty AS invjit FROM snitch_db.maplemonk.offline_master WHERE new_category IN ( \'Sunglasses\', \'Accessories\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\' ) AND branch_code IN ( 3,4,6,7,13,14,15,18,19,21,22,23,26,29,30,38,39,40,42,47,49,50,51,52, 56,57,64,68,69,73,75,77,79,82,85,86,87,88,89,90,91,96,97,99,100,102, 103,104,106,107,109,110,111,114,116,120,123,125,128,130,132,134,135, 136,139,141,142 ) AND INVENTORY + JIT_QTY > 0 AND sku_group NOT LIKE \'%GIFT%\' AND NOT ( new_category = \'Shoes\' AND branch_code IN (13, 14, 82, 85, 90)) ), full_exposed_stores as ( select branch_code, upper(sku_group) as sku_group from snitch_db.maplemonk.offline_master where branch_code in (120, 123, 139, 56) and inventory + jit_qty > 0 and UPPER(sku_group) not like \'%GIFT%\' ), bday_sale_skus as ( select \"SKU Group\" as bday_skus from snitch_db.maplemonk.final_discount_skus_sheet1 where lower(category) like \'%bday%\' ), bday_sale_branch_skus AS ( SELECT bc.branch_code, UPPER(bs.bday_skus) AS sku_group FROM ( SELECT column1 AS branch_code FROM VALUES (3),(4),(6),(7),(13),(14),(15),(18),(19),(21),(22),(23), (26),(29),(30),(38),(39),(40),(42),(47),(49),(50),(51),(52), (56),(57),(64),(68),(69),(73),(75),(77),(79),(82),(85),(86), (87),(88),(89),(90),(91),(96), (97),(99),(100),(102),(103),(104), (106),(107),(109),(110),(111),(114),(116),(120),(123),(125), (128),(130),(132),(134),(135),(136),(139),(141),(142) ) bc CROSS JOIN bday_sale_skus bs ), offline_inv_check AS ( SELECT branch_code, UPPER(sku_group) AS sku_group, COALESCE(inventory, 0) + COALESCE(jit_qty, 0) AS ttl_inventory FROM snitch_db.maplemonk.offline_master ), bday_sale_branch_skus_inv AS ( SELECT b.branch_code, b.sku_group FROM bday_sale_branch_skus b JOIN offline_inv_check o ON b.branch_code = o.branch_code AND b.sku_group = o.sku_group WHERE o.ttl_inventory > 0 ), combined AS ( SELECT branch_code, UPPER(sku_group) AS sku_group, \'LOW_STR_SKUS\' AS source_type FROM low_str_skus UNION ALL SELECT branch_code, UPPER(sku_group) AS sku_group, \'NO_REPLEN_SKUS\' AS source_type FROM no_replen_skus UNION ALL SELECT branch_code, UPPER(sku_group) AS sku_group, \'LONG_TAIL\' AS source_type FROM long_tail UNION ALL SELECT branch_code, UPPER(sku_group) AS sku_group, \'BDAY_SALE\' AS source_type FROM bday_sale_branch_skus_inv UNION ALL SELECT branch_code, UPPER(sku_group) AS sku_group, \'FULL_EXP\' AS source_type FROM full_exposed_stores ) SELECT branch_code, sku_group, LISTAGG(DISTINCT source_type, \', \') WITHIN GROUP (ORDER BY source_type) AS type FROM combined WHERE sku_group NOT LIKE \'%GIFT%\' GROUP BY branch_code, sku_group ORDER BY branch_code, sku_group;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            